<!DOCTYPE html>
<html lang="id">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Scorely — TOEFL Practice Lab</title>
    <link rel="preconnect" href="https://fonts.googleapis.com">
    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
    <link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Syne:wght@600;700;800&display=swap" rel="stylesheet">
    <style>
        :root { --ink:#19251f; --muted:#718077; --line:#dce5df; --cream:#f6f8f3; --lime:#c7f36b; --teal:#135e56; --orange:#f18d54; }
        * { box-sizing:border-box } body { margin:0; color:var(--ink); background:var(--cream); font-family:'DM Sans',sans-serif; }
        button { font:inherit; cursor:pointer; border:0 } .shell { min-height:100vh; overflow:hidden; }
        .nav { height:76px; display:flex; align-items:center; justify-content:space-between; padding:0 6vw; border-bottom:1px solid var(--line); background:rgba(246,248,243,.9); }
        .brand { display:flex; align-items:center; gap:10px; font-family:Syne,sans-serif; font-size:21px; font-weight:800; letter-spacing:-.05em; }
        .brand-mark { width:31px; height:31px; display:grid; place-items:center; color:var(--ink); background:var(--lime); border-radius:10px 10px 10px 3px; font-size:17px; }
        .nav-links { display:flex; gap:30px; color:var(--muted); font-size:13px; font-weight:600; } .nav-links a { color:inherit; text-decoration:none; }
        .nav-cta, .primary { background:var(--ink); color:white; border-radius:999px; padding:12px 20px; font-weight:700; font-size:13px; transition:.2s; } .nav-cta:hover,.primary:hover { transform:translateY(-2px); background:var(--teal); }
        .hero { max-width:1160px; margin:0 auto; padding:76px 28px 52px; display:grid; grid-template-columns:1.04fr .96fr; gap:50px; align-items:center; }
        .eyebrow { display:inline-flex; gap:8px; align-items:center; color:var(--teal); text-transform:uppercase; letter-spacing:.14em; font-size:11px; font-weight:800; } .dot { width:7px;height:7px;background:var(--orange);border-radius:50%; }
        h1,h2,h3 { font-family:Syne,sans-serif; letter-spacing:-.055em; line-height:1.04; margin:0; } h1 { font-size:clamp(45px,6vw,79px); max-width:650px; margin:17px 0 22px; } h1 em { color:var(--teal); font-style:normal; } .hero-copy { color:var(--muted); font-size:16px; line-height:1.7; max-width:480px; }
        .hero-actions { margin-top:32px; display:flex; align-items:center; gap:18px; } .ghost { color:var(--ink); background:none; font-weight:700; font-size:13px; } .play { width:32px;height:32px; display:inline-grid;place-items:center;border:1px solid var(--line);border-radius:50%;margin-right:8px;font-size:11px; }
        .score-card { background:var(--teal); color:white; border-radius:28px; padding:28px; min-height:367px; position:relative; overflow:hidden; box-shadow:0 18px 50px rgba(19,94,86,.18); } .score-card:after { content:''; position:absolute; width:270px;height:270px;border:1px solid rgba(199,243,107,.34);border-radius:50%;right:-75px;bottom:-94px;box-shadow:0 0 0 28px rgba(199,243,107,.09),0 0 0 56px rgba(199,243,107,.07); }
        .card-top { display:flex;justify-content:space-between;align-items:center;position:relative;z-index:1; } .card-label { font-size:12px; color:#b8dfd4; } .badge { background:var(--lime);color:var(--ink);font-weight:800;font-size:11px;padding:7px 11px;border-radius:999px; }
        .score-num { font-family:Syne,sans-serif;font-size:96px;letter-spacing:-.09em;margin:43px 0 3px;position:relative;z-index:1; } .score-sub { color:#b8dfd4;font-size:13px;position:relative;z-index:1; } .bar { margin-top:29px;height:8px;background:#367b71;border-radius:9px;overflow:hidden;position:relative;z-index:1; } .bar span { display:block;width:78%;height:100%;background:var(--lime);border-radius:9px; }
        .mini-stats { display:flex;gap:32px;margin-top:17px;position:relative;z-index:1; }.mini-stats strong{display:block;font-size:16px}.mini-stats small{color:#b8dfd4;font-size:11px}
        .section { max-width:1160px;margin:0 auto;padding:30px 28px 85px; } .section-head { display:flex;justify-content:space-between;align-items:end;margin-bottom:24px; } .section-head h2{font-size:34px;max-width:430px}.section-head p{color:var(--muted);font-size:13px;max-width:270px;line-height:1.6;margin:0}.cards { display:grid;grid-template-columns:repeat(3,1fr);gap:16px; }
        .module { background:white;border:1px solid var(--line);border-radius:19px;padding:22px;min-height:215px;transition:.2s;position:relative; }.module:hover { transform:translateY(-4px);box-shadow:0 12px 30px rgba(25,37,31,.06); }.module-icon{width:41px;height:41px;display:grid;place-items:center;border-radius:13px;margin-bottom:22px;font-size:19px}.ic-1{background:#eef7c9}.ic-2{background:#ffeadc}.ic-3{background:#dff0ed}.module h3{font-size:20px;margin-bottom:8px}.module p{color:var(--muted);font-size:12px;line-height:1.55;margin:0 0 18px}.module-foot{font-size:11px;color:var(--teal);font-weight:800;display:flex;justify-content:space-between}.practice { display:none; max-width:920px; margin:0 auto; padding:42px 28px 80px; }.practice.active{display:block}.home.hidden{display:none}.test-head{display:flex;align-items:center;justify-content:space-between;margin-bottom:30px}.test-title{font-size:30px}.timer{background:white;border:1px solid var(--line);padding:10px 15px;border-radius:11px;font-family:monospace;font-weight:700;color:var(--teal)}.progress{height:5px;background:#e2eae4;border-radius:8px;margin-bottom:34px}.progress span{display:block;height:100%;background:var(--orange);border-radius:8px;transition:.3s}.question-label{color:var(--orange);font-weight:800;font-size:11px;letter-spacing:.12em;text-transform:uppercase}.question{font-family:Syne,sans-serif;font-size:29px;line-height:1.25;margin:13px 0 25px;letter-spacing:-.04em}.options{display:grid;gap:11px}.option{background:white;border:1px solid var(--line);border-radius:13px;padding:16px 18px;text-align:left;display:flex;gap:13px;align-items:center;transition:.2s;color:var(--ink);}.option:hover{border-color:#a1c8b5}.option.selected{border-color:var(--teal);background:#eaf4ed;box-shadow:0 0 0 2px rgba(19,94,86,.08)}.option-letter{width:25px;height:25px;display:grid;place-items:center;border:1px solid #cad8cf;border-radius:7px;font-size:12px;font-weight:800;flex:none}.option.selected .option-letter{background:var(--teal);color:white;border-color:var(--teal)}.test-foot{display:flex;justify-content:space-between;align-items:center;margin-top:38px}.back{background:none;color:var(--muted);font-weight:700;font-size:13px}.next{background:var(--teal);color:white;border-radius:10px;padding:13px 22px;font-weight:700;font-size:13px}.question-map{margin-top:40px;padding-top:20px;border-top:1px solid var(--line);display:flex;gap:7px;flex-wrap:wrap}.map-dot{width:29px;height:29px;border-radius:8px;background:white;border:1px solid var(--line);font-size:11px;color:var(--muted)}.map-dot.current{background:var(--ink);color:white}.map-dot.done{background:var(--lime);color:var(--ink);border-color:var(--lime)}.result{display:none;text-align:center;padding:70px 20px}.result.active{display:block}.result h2{font-size:48px;margin:15px auto;max-width:600px}.result-score{font-family:Syne;font-size:80px;color:var(--teal);margin:22px 0 5px}.result p{color:var(--muted);line-height:1.6}.result-actions{margin-top:28px}.footer{padding:22px 6vw;border-top:1px solid var(--line);font-size:12px;color:var(--muted);display:flex;justify-content:space-between}.toast{position:fixed;bottom:22px;left:50%;transform:translate(-50%,20px);opacity:0;background:var(--ink);color:white;padding:12px 17px;border-radius:10px;font-size:12px;transition:.25s;pointer-events:none}.toast.show{opacity:1;transform:translate(-50%,0)}
        @media(max-width:760px){.nav{padding:0 20px}.nav-links{display:none}.hero{display:block;padding:48px 20px 34px}.hero h1{font-size:53px}.score-card{margin-top:40px}.section{padding:26px 20px 60px}.section-head{display:block}.section-head p{margin-top:12px}.cards{grid-template-columns:1fr}.practice{padding:30px 20px 60px}.test-head{align-items:flex-start;gap:15px;flex-direction:column}.question{font-size:24px}.footer{padding:20px;display:block}.footer span{display:block;margin-top:5px}}
    </style>
</head>
<body>
<div class="shell">
    <nav class="nav"><a class="brand" href="#"><span class="brand-mark">S</span> scorely</a><div class="nav-links"><a href="#modules">Practice</a><a href="#method">How it works</a><a href="#about">About</a></div><button class="nav-cta" onclick="startTest()">Try a mock test →</button></nav>
    <main id="home" class="home">
        <section class="hero"><div><div class="eyebrow"><span class="dot"></span> TOEFL iBT preparation</div><h1>Your score is a <em>skill</em> you can build.</h1><p class="hero-copy">Latihan TOEFL yang terasa lebih terarah. Simulasikan tes, pahami pola soal, dan bangun kepercayaan diri untuk hari ujian.</p><div class="hero-actions"><button class="primary" onclick="startTest()">Start a free mock test&nbsp; ↗</button><button class="ghost" onclick="showToast('Video panduan segera hadir')"><span class="play">▶</span>See how it works</button></div></div><div class="score-card"><div class="card-top"><span class="card-label">Latest practice score</span><span class="badge">+12 pts</span></div><div class="score-num">92</div><div class="score-sub">Your estimated TOEFL iBT score</div><div class="bar"><span></span></div><div class="mini-stats"><div><strong>24 / 30</strong><small>Reading</small></div><div><strong>23 / 30</strong><small>Listening</small></div><div><strong>25 / 30</strong><small>Grammar</small></div></div></div></section>
        <section class="section" id="modules"><div class="section-head"><h2>Everything you need to move forward.</h2><p>Short, focused practice that fits into your day — and compounds over time.</p></div><div class="cards"><article class="module" onclick="startTest()"><div class="module-icon ic-1">✦</div><h3>Mock tests</h3><p>Feel the real test experience with timed, exam-style questions.</p><div class="module-foot"><span>10 questions · 12 min</span><span>→</span></div></article><article class="module" onclick="showToast('Section Reading sedang disiapkan')"><div class="module-icon ic-2">◒</div><h3>Skill practice</h3><p>Sharpen Reading, Listening, and Grammar with targeted exercises.</p><div class="module-foot"><span>3 skill areas</span><span>→</span></div></article><article class="module" onclick="showToast('Progress tersimpan di perangkat ini')"><div class="module-icon ic-3">↗</div><h3>Track progress</h3><p>See where you are improving and what to focus on next.</p><div class="module-foot"><span>Personal insights</span><span>→</span></div></article></div></section>
    </main>
    <section id="practice" class="practice"><div class="test-head"><div><div class="eyebrow"><span class="dot"></span> Quick mock test</div><h2 class="test-title">Reading & grammar</h2></div><div class="timer" id="timer">12:00</div></div><div class="progress"><span id="progressBar" style="width:10%"></span></div><div class="question-label" id="questionCount">Question 01 / 10</div><div class="question" id="questionText"></div><div class="options" id="options"></div><div class="test-foot"><button class="back" onclick="quitTest()">← Exit test</button><button class="next" id="nextBtn" onclick="nextQuestion()">Next question&nbsp; →</button></div><div class="question-map" id="questionMap"></div></section>
    <section id="result" class="result"><div class="eyebrow" style="justify-content:center"><span class="dot"></span> Test complete</div><h2>Nice work. Keep the momentum going.</h2><div class="result-score" id="resultScore">—</div><p id="resultMessage">Your estimated score is based on this quick practice.</p><div class="result-actions"><button class="primary" onclick="startTest()">Try again&nbsp; ↗</button><button class="ghost" onclick="quitTest()">Back to home</button></div></section>
    <footer class="footer"><span>© 2026 scorely</span><span>Built for ambitious learners · Your data stays on this device</span></footer>
</div><div class="toast" id="toast"></div>
<script>
const questions=[
 {q:'The research team _____ its findings in a journal next month.',o:['publishes','will publish','publishing','publish'],a:1},
 {q:'The word “significant” in the passage is closest in meaning to …',o:['temporary','important','unexpected','complex'],a:1},
 {q:'Neither the students nor the instructor _____ aware of the schedule change.',o:['were','have','was','are'],a:2},
 {q:'What is the main purpose of the passage?',o:['To compare two theories','To describe a recent discovery','To criticize a common practice','To explain a historical event'],a:1},
 {q:'The new policy will take effect _____ the beginning of the semester.',o:['at','in','on','by'],a:0},
 {q:'According to the speaker, the project was delayed because …',o:['funding was unavailable','the design needed revision','the weather was unusually severe','the team changed its goals'],a:1},
 {q:'The museum offers free admission to visitors _____ arrive before noon.',o:['which','whose','who','whom'],a:2},
 {q:'The author implies that the results should be interpreted with …',o:['confidence','caution','urgency','enthusiasm'],a:1},
 {q:'By the time the lecture began, the professor _____ the slides.',o:['prepared','has prepared','had prepared','prepares'],a:2},
 {q:'Which statement best summarizes the text?',o:['A problem remains unsolved.','A traditional idea was confirmed.','A new approach shows promise.','A debate has ended.'],a:2}
];
let current=0, answers=Array(questions.length).fill(null), seconds=720, timerId=null;
function startTest(){document.getElementById('home').classList.add('hidden');document.getElementById('result').classList.remove('active');document.getElementById('practice').classList.add('active');current=0;answers=Array(questions.length).fill(null);seconds=720;clearInterval(timerId);timerId=setInterval(()=>{seconds--;updateTimer();if(seconds<=0)finishTest()},1000);renderQuestion();window.scrollTo({top:0,behavior:'smooth'})}
function updateTimer(){let m=String(Math.floor(seconds/60)).padStart(2,'0'),s=String(seconds%60).padStart(2,'0');document.getElementById('timer').textContent=m+':'+s; if(seconds<60)document.getElementById('timer').style.color='#d15a45'}
function renderQuestion(){let x=questions[current];document.getElementById('questionCount').textContent=`Question ${String(current+1).padStart(2,'0')} / ${questions.length}`;document.getElementById('questionText').textContent=x.q;document.getElementById('progressBar').style.width=((current+1)/questions.length*100)+'%';document.getElementById('options').innerHTML=x.o.map((v,i)=>`<button class="option ${answers[current]===i?'selected':''}" onclick="choose(${i})"><span class="option-letter">${String.fromCharCode(65+i)}</span><span>${v}</span></button>`).join('');document.getElementById('nextBtn').textContent=current===questions.length-1?'Finish test  ✓':'Next question  →';document.getElementById('questionMap').innerHTML=questions.map((_,i)=>`<button class="map-dot ${i===current?'current':''} ${answers[i]!==null?'done':''}" onclick="jump(${i})">${i+1}</button>`).join('')}
function choose(i){answers[current]=i;renderQuestion()} function jump(i){current=i;renderQuestion()} function nextQuestion(){if(answers[current]===null){showToast('Pilih satu jawaban dulu');return}if(current<questions.length-1){current++;renderQuestion()}else finishTest()}
function finishTest(){clearInterval(timerId);let correct=answers.reduce((n,a,i)=>n+(a===questions[i].a?1:0),0);let score=Math.round(40+(correct/10)*70);document.getElementById('practice').classList.remove('active');document.getElementById('result').classList.add('active');document.getElementById('resultScore').textContent=score+' / 120';document.getElementById('resultMessage').textContent=`Kamu menjawab ${correct} dari ${questions.length} soal dengan benar. Ulangi latihan untuk meningkatkan skor secara konsisten.`;window.scrollTo({top:0,behavior:'smooth'})}
function quitTest(){clearInterval(timerId);document.getElementById('practice').classList.remove('active');document.getElementById('result').classList.remove('active');document.getElementById('home').classList.remove('hidden');window.scrollTo({top:0,behavior:'smooth'})}
function showToast(msg){let t=document.getElementById('toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2300)}
</script>
</body></html>
